'use client';

import { createContext, useCallback, useContext, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import type { ReactNode } from 'react';
import { ChevronDownIcon, ChevronUpIcon, XIcon } from 'lucide-react';
import * as NativeDrawer from '@base-ui/react/drawer';
import { Drawer, DrawerSwipeHandle, DrawerTitle } from '@/components/ui/drawer';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { PiChat } from '../pi-chat/pi-chat';
import { ChatTextProvider } from '../pi-chat/labels';
import { chatTextFor } from '../pi-chat/locale';
import { withChatPlugins } from '../pi-chat-plugins/chat-plugins';
import { PmComposer } from './pm-composer';
import { usePmPanel } from './use-pm-panel';
import { POINT_PREFACE, pointMessage } from './point-message';
import { useTaskMentions } from './task-mentions';
import type { ImproveSpec } from './use-pm-panel';
import { cn } from '../utils/utils';

export { PmComposer } from './pm-composer';
export { usePmPanel } from './use-pm-panel';
export type { PmComposerProps } from './pm-composer';
export { useTaskMentions } from './task-mentions';
export type { TaskMention, TaskMentionSource } from './task-mentions';
export type { ImproveSpec, PmVoice, PmTranscript, StudioTaskBoardSeam } from './use-pm-panel';

interface Binding { readonly spec: ImproveSpec; readonly open: boolean; readonly close: () => void }
async function imageFiles(files: readonly File[]) {
  return Promise.all(files.map(async (file, index) => {
    if (!/^image\/(png|jpeg|gif|webp)$/.test(file.type) || file.size > 3 * 1024 * 1024) throw new Error('Joignez une image de moins de 3 Mo.');
    let binary = '';
    for (const byte of new Uint8Array(await file.arrayBuffer())) binary += String.fromCharCode(byte);
    return { id: `pm-file-${Date.now()}-${index}`, name: file.name, content: { type: 'image' as const, mimeType: file.type, data: btoa(binary) } };
  }));
}

const PmContext = createContext<Binding | null>(null);
const SelectingContext = createContext(false);
export const usePmSelecting = () => useContext(SelectingContext);

export function PmPanelProvider({ spec, open, close, children }: { readonly spec?: ImproveSpec | undefined; readonly open: boolean; readonly close: () => void; readonly children: ReactNode }) {
  const value = useMemo(() => spec ? { spec, open, close } : null, [spec, open, close]);
  return <PmContext.Provider value={value}>{children}</PmContext.Provider>;
}

/** The app's content and tab bar remain in flow. The PM takes space, never a viewport overlay. */
export function ImproveLayout({ children, navigation, screen }: { readonly children: ReactNode; readonly navigation?: ReactNode; readonly screen?: string }) {
  const binding = useContext(PmContext);
  return <BoundLayout binding={binding} navigation={navigation} screen={screen}>{children}</BoundLayout>;
}

function BoundLayout({ binding, children, navigation, screen }: { readonly binding: Binding | null; readonly children: ReactNode; readonly navigation?: ReactNode; readonly screen: string | undefined }) {
  const [page, setPage] = useState<HTMLDivElement | null>(null);
  const controller = binding?.spec.controller;
  const [instance, setInstance] = useState({ controller, sequence: 0 });
  if (instance.controller !== controller) setInstance({ controller, sequence: instance.sequence + 1 });
  const [placement, setPlacement] = useState({ controller, mode: 'sheet', show: false });
  const report = useCallback((controller: ImproveSpec['controller'], mode: string, show: boolean) => setPlacement(current => current.controller === controller && current.mode === mode && current.show === show ? current : { controller, mode, show }), []);
  const current = placement.controller === controller ? placement : { mode: 'sheet', show: false };
  const strip = current.mode === 'point' || current.mode === 'navigate';
  return <SelectingContext.Provider value={Boolean(binding?.open && current.show)}><div data-pm-layout="" className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden">
    <div ref={setPage} data-pm-page="" data-pm-screen={screen} className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden">{children}</div>
    {binding && <PanelSession key={instance.sequence} binding={binding} page={page} screen={screen} report={report} />}
    <div data-pm-navigation="" hidden={Boolean(binding?.open && !strip)} className="shrink-0">{navigation}</div>
  </div></SelectingContext.Provider>;
}

function PanelSession({ binding, page, screen, report }: { readonly binding: Binding; readonly page: HTMLElement | null; readonly screen: string | undefined; readonly report: (controller: ImproveSpec['controller'], mode: string, show: boolean) => void }) {
  const pm = usePmPanel(binding.spec, binding.open, page, screen);
  const { mode, show } = pm.state;
  useLayoutEffect(() => { report(binding.spec.controller, mode, show); }, [binding.spec.controller, mode, show, report]);
  return <Panel binding={binding} pm={pm} strip={mode === 'point' || mode === 'navigate'} full={mode === 'full'} />;
}

function Panel({ binding: { spec, open, close }, pm, strip, full }: { readonly binding: Binding; readonly pm: ReturnType<typeof usePmPanel>; readonly strip: boolean; readonly full: boolean }) {
  const [requests, setRequests] = useState(false);
  const mentions = useTaskMentions(spec.taskMentions, spec.chatProps?.mentions);
  const sheet = useRef<HTMLDivElement | null>(null);
  const [portal, setPortal] = useState<HTMLDivElement | null>(null);
  const submit = pm.sendContext;
  const { dispatch } = pm;
  // Plain-text sends have no context attachment, but still expand on observed native admission.
  const admitted = pm.snapshot.send.kind === 'admitted' ? pm.snapshot.send.attempt.requestId : undefined;
  const previousAdmission = useRef<string | undefined>(undefined);
  useEffect(() => {
    if (admitted && admitted !== previousAdmission.current) dispatch({ type: 'full' });
    if (admitted) previousAdmission.current = admitted;
  }, [admitted, dispatch]);
  const uncertain = pm.snapshot.send.kind === 'unknown' ? pm.snapshot.send.attempt : undefined;
  const focusVersion = pm.focusVersion;
  useEffect(() => {
    if (!focusVersion || !open || strip) return;
    const input = sheet.current?.querySelector<HTMLElement>('[data-testid=composer-input]');
    input?.focus({ preventScroll: true });
    if (input instanceof HTMLTextAreaElement) input.setSelectionRange(input.value.length, input.value.length);
  }, [focusVersion, open, strip, spec.controller]);
  const show = (value: boolean) => pm.dispatch({ type: 'show', value });
  const pointProps = { selections: pm.state.chips, onRemove: pm.remove, show: pm.state.show, onShow: show, onReturn: pm.returnToComposer,
    onOpenRecorder: () => pm.dispatch({ type: 'return' }), focusInput: focusVersion > 0 && open && !strip, voice: pm.voice };
  const text = chatTextFor(spec.chatProps?.locale ?? 'fr');
  const transcript = pm.voice.phase === 'processing' ? <p data-testid="pm-transcribing" role="status" className="m-0 px-2">Transcription…</p> : pm.liveText && <p role="status" data-testid="pm-live-transcript" className="m-0 px-2">{pm.liveText}</p>;
  return <section hidden={!open} data-feedback-ignore="" data-testid="pm-panel" data-mode={pm.state.mode} className={cn('min-h-0 shrink-0', open && !strip && (full ? 'flex h-[min(65dvh,42rem)] flex-col' : 'flex max-h-[55dvh] flex-col'))}>
    <ChatTextProvider value={text}>
      <div hidden={!strip}><PmComposer variant="strip" {...pointProps} /></div>
      {/* The native portal targets an in-flow host, never the viewport/body overlay. */}
      <div hidden={strip} ref={setPortal} className="min-h-0 flex-1">
        {portal && <Drawer open={open && !strip} modal={false} showSwipeHandle onOpenChange={(next, details) => {
          if (next || !open || strip) return;
          if (details.reason === 'swipe') pm.dispatch({ type: 'show', value: true });
          else if (details.reason === 'escape-key') close();
        }}>
          <NativeDrawer.Drawer.Portal container={portal} keepMounted className="flex h-full min-h-0 flex-col"><NativeDrawer.Drawer.Viewport className="flex h-full min-h-0 flex-col"><NativeDrawer.Drawer.Popup render={<Card />} ref={sheet} initialFocus={false} finalFocus={false} data-testid="pm-sheet" data-swipe-axis="y" data-swipe-direction="down" className="group/drawer-popup flex h-full min-h-0 flex-col gap-0 overflow-hidden py-0">
            <DrawerSwipeHandle />
            <div className="flex min-h-11 shrink-0 items-center gap-1 px-3">
              <DrawerTitle className="min-w-0 flex-1">Améliorer l’app</DrawerTitle>
              {full && <Button variant="link" data-testid="pm-requests" disabled={!spec.tasks} onClick={() => setRequests(value => !value)}>Mes demandes</Button>}
              <Button variant="ghost" size="icon" aria-label={full ? 'Réduire' : 'Ouvrir le panneau'} data-testid="pm-expand" onClick={() => pm.dispatch({ type: full ? 'collapse' : 'full' })}>{full ? <ChevronDownIcon data-icon="inline-start" /> : <ChevronUpIcon data-icon="inline-start" />}</Button>
              <Button variant="ghost" size="icon" aria-label="Fermer" data-testid="pm-close" onClick={close}><XIcon data-icon="inline-start" /></Button>
            </div>
            <NativeDrawer.Drawer.Content data-base-ui-swipe-ignore="" className="flex min-h-0 flex-1 flex-col overflow-hidden">
              {pm.problem && <p role="alert" className="m-0 px-4">{pm.problem}</p>}
              {full && requests && spec.tasks && <div className="min-h-0 flex-1 overflow-auto" data-testid="pm-task-board-seam">{spec.tasks.renderBoard({ filter: 'mine', variant: 'full' })}</div>}
              <div className={cn('min-h-0 flex-1', full && requests ? 'hidden' : 'flex flex-col', !full && '[&_[data-testid=transcript]]:hidden [&_[data-boring=pi-chat]>.relative]:hidden [&_[data-boring=pi-chat]>footer]:pt-0')}>
                <PiChat {...withChatPlugins({ ...spec.chatProps, ...(mentions ? { mentions } : {}) })} controller={spec.controller} locale={spec.chatProps?.locale ?? 'fr'} header={false} emptyLayout="docked" keyboardInset={false}
                  labels={{ ...spec.chatProps?.labels, placeholder: 'Décrivez le problème, ou ↖ pour me le montrer.' }} onFiles={spec.chatProps?.onFiles ?? imageFiles}
                  sendContext={submit} renderEntry={entry => pointMessage(entry, mentions) ?? spec.chatProps?.renderEntry?.(entry)} renderComposer={composer => <PmComposer {...pointProps} composer={{ ...composer, sendBlocked: composer.sendBlocked || pm.voice.phase === 'processing' || pm.snapshot.send.kind === 'validating' || pm.snapshot.send.kind === 'submitting', ...(uncertain ? { text: uncertain.draft.text.split(POINT_PREFACE)[0]!.trimEnd(), disabled: true } : {}) }} transcript={transcript} />}
                  belowComposer={full ? <>{spec.tasks?.renderRequest?.()}{spec.tasks?.renderBoard({ filter: 'mine', limit: 2, variant: 'compact' })}</> : undefined} />
              </div>
            </NativeDrawer.Drawer.Content>
          </NativeDrawer.Drawer.Popup></NativeDrawer.Drawer.Viewport></NativeDrawer.Drawer.Portal>
        </Drawer>}
      </div>
    </ChatTextProvider>
  </section>;
}

'use client';

import type { ReactNode } from 'react';
import { HandIcon, MicIcon, MousePointer2Icon, PauseIcon, XIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { ToggleGroup, ToggleGroupItem } from '@/components/ui/toggle-group';
import { Composer } from '../pi-chat/composer';
import type { ComposerProps } from '../pi-chat/composer';
import type { VoiceMessageHandle } from '../pi-chat/config';
import { voiceClock } from '../pi-chat/config';
import { RecordingBar, VoiceMessageButton } from '../pi-chat-voice/voice-message';
import { InlinePointInput } from './inline-point-input';
import type { PointChip } from './point-state';

/** One composer for a sheet, a conversation column or an ambient bar. The host owns placement, admission and capture. */
export interface PmComposerProps {
  readonly variant?: 'composer' | 'strip';
  readonly composer?: ComposerProps;
  readonly selections?: readonly PointChip[];
  readonly onRemove?: (id: string) => void;
  readonly show: boolean;
  readonly onShow: (show: boolean) => void;
  readonly onReturn?: () => void;
  readonly onOpenRecorder?: () => void;
  readonly focusInput?: boolean;
  readonly voice?: VoiceMessageHandle;
  readonly transcript?: ReactNode;
}
const noSelections: readonly PointChip[] = [];
const silentVoice: VoiceMessageHandle = { canStart: false, phase: 'idle', seconds: 0, captureSequence: 0, pending: [], problem: undefined, start() {}, finish() {}, cancel() {} };

export function PmComposer({ variant = 'composer', composer, selections = noSelections, onRemove, show, onShow, onReturn, onOpenRecorder, focusInput, voice, transcript }: PmComposerProps) {
  const recording = voice?.phase === 'starting' || voice?.phase === 'recording';
  if (variant === 'strip') return <div data-feedback-ignore="" data-pm-strip="" data-testid="pm-strip" data-pointing={show} className="flex h-14 min-h-14 shrink-0 items-center gap-1 bg-foreground px-2 text-background">
    {recording && <ToggleGroup variant="outline" value={[show ? 'select' : 'navigate']} onValueChange={values => { if (values[0]) onShow(values[0] === 'select'); }} role="radiogroup" aria-label="Mode de pointage">
      <ToggleGroupItem value="select" role="radio" aria-checked={show} aria-label="Sélectionner" data-testid="pm-select" className="min-h-11 min-w-11"><MousePointer2Icon data-icon="inline-start" className={show ? 'text-foreground' : 'text-background'} /></ToggleGroupItem>
      <ToggleGroupItem value="navigate" role="radio" aria-checked={!show} aria-label="Naviguer" data-testid="pm-navigate" className="min-h-11 min-w-11"><HandIcon data-icon="inline-start" className={show ? 'text-background' : 'text-foreground'} /></ToggleGroupItem>
    </ToggleGroup>}
    <span className="min-w-0 flex-1 text-xs">{!recording ? 'Touchez ce que vous voulez montrer' : show ? 'Parlez et touchez ce que vous montrez' : 'Sélection en pause'}</span>
    {recording && <Button variant="ghost" size="sm" aria-label="Ouvrir le dictaphone" data-testid="pm-timer" onClick={onOpenRecorder} className="min-h-11"><span className="whitespace-nowrap tabular-nums"><span className="text-destructive">●</span> {voiceClock(voice?.seconds ?? 0)}</span></Button>}
    {recording ? <Button variant="ghost" size="icon" aria-label={voice.paused ? 'Reprendre' : 'Pause'} data-testid="pm-pause" disabled={!voice.pause} onClick={voice.paused ? voice.resume : voice.pause} className="min-h-11 min-w-11">{voice.paused ? <MicIcon data-icon="inline-start" /> : <PauseIcon data-icon="inline-start" />}</Button>
      : <VoiceMessageButton voice={voice ?? silentVoice} testId="pm-mic" />}
    <Button variant="ghost" size="icon" aria-label="Terminé" data-testid="pm-done" onClick={onReturn} className="min-h-11 min-w-11"><XIcon data-icon="inline-start" /></Button>
  </div>;
  if (!composer) throw new Error('PmComposer needs composer props outside strip mode');
  const toggle = <Button variant="ghost" size="icon" disabled={composer.disabled || composer.sendBlocked} aria-pressed={show} onClick={() => onShow(!show)} data-testid="pm-show" aria-label="Montrer" title="Montrer" className="min-h-11 min-w-11"><MousePointer2Icon data-icon="inline-start" /></Button>;
  const selected = new Set(selections.map(chip => chip.id));
  return <div data-feedback-ignore="" data-testid="pm-composer" className="flex min-w-0 flex-col gap-2 [&_[data-testid=composer-controls]_button]:min-h-11 [&_[data-testid=composer-controls]_button]:min-w-11">
    {transcript}
    <Composer {...composer} attachments={composer.attachments.filter(image => !selected.has(image.id))}
      renderInput={selections.length ? ({ text, onText, onCaret, onSend }) => <InlinePointInput text={text} selections={selections} onText={onText} onCaret={onCaret} onRemove={id => onRemove?.(id)} onSend={onSend} disabled={composer.disabled} focus={focusInput} /> : composer.renderInput}
      placeholderContent={<>Décrivez le problème, ou <MousePointer2Icon className="inline size-4 align-text-bottom" aria-hidden="true" /> pour me le montrer.</>} chips={<>{toggle}{composer.chips}</>}
      recording={recording && voice ? <div className="flex w-full min-w-0 items-center gap-1">{toggle}<RecordingBar voice={voice} testId="pm-voice-send" /></div> : composer.recording}
      barEnd={<>{composer.barEnd}{voice && !recording && <VoiceMessageButton voice={voice} testId="pm-mic" />}</>} />
  </div>;
}

'use client';

import { useCallback, useEffect, useId, useLayoutEffect, useMemo, useReducer, useRef, useState, useSyncExternalStore } from 'react';
import { anchorOf, createOverlay, createPicker, createPrivacyPolicy } from '@hachej/boring-feedback/page';
import type { PrivacyPolicy, SpeechSegment } from '@hachej/boring-feedback/page';
import { useVoiceAttempt } from '@hachej/boring-ui-kit/chat-react/voice';
import { appendToDraft, voiceRefusalLabel } from '@hachej/boring-ui-kit/chat-text';
import type { VoiceMessageHandle, VoiceMessageConfig } from '../pi-chat/config';
import type { PiChatProps } from '../pi-chat/pi-chat';
import type { NativeChatController } from '@hachej/boring-ui-kit/native-chat';
import { frenchChatLabels } from '../pi-chat/labels-fr';
import { feedbackLabelsFr } from '../feedback/feedback-labels';
import type { PointChip } from './point-state';
import { alignedTranscript, createPointState, marker, pointReducer } from './point-state';
import { captureElement } from './capture';
import { POINT_PREFACE } from './point-message';

export interface PmTranscript { readonly text: string; readonly segments?: readonly SpeechSegment[] }
/** Optional host voice enrichment. Authorization, retention and transcription remain with the host. */
export interface PmVoice {
  readonly transcribe: (audio: Blob, signal: AbortSignal) => Promise<string | PmTranscript>;
  readonly maxMs?: number;
  /** Optional live text with timings. The returned cleanup releases only this capture's listener. */
  readonly live?: (signal: AbortSignal, update: (transcript: PmTranscript) => void) => (() => void);
}
export interface ImproveSpec {
  readonly controller: NativeChatController;
  readonly chatProps?: Omit<PiChatProps, 'controller'>;
  readonly label?: string;
  readonly voice?: VoiceMessageConfig & { readonly send?: 'auto' | 'draft' | 'message' };
  readonly feedback?: import('@hachej/boring-feedback/ui').FeedbackSession;
  readonly policy?: PrivacyPolicy;
  readonly pointVoice?: PmVoice;
  readonly tasks?: StudioTaskBoardSeam;
  readonly taskMentions?: import('./task-mentions').TaskMentionSource;
}
/** D-417 / PR #1900 owns these components; this is deliberately not another card or board. */
export interface StudioTaskBoardSeam {
  readonly renderBoard: (options: { readonly filter: 'mine'; readonly variant: 'full' | 'compact'; readonly limit?: number }) => import('react').ReactNode;
  readonly renderRequest?: () => import('react').ReactNode;
}

interface CaptureBatch {
  readonly context: object;
  readonly controller: NativeChatController;
  readonly ids: readonly string[];
  readonly text: string;
  readonly speech: PmTranscript;
  readonly priorRequestId: string | undefined;
  requestId?: string;
}
const defaultPolicy = createPrivacyPolicy();
function keepMarkers(controller: NativeChatController, chips: readonly PointChip[]) {
  const text = controller.getSnapshot().draft.text;
  const missing = chips.filter(chip => !text.includes(marker(chip.number))).map(chip => marker(chip.number)).join(' ');
  if (missing) controller.setText(appendToDraft(text, missing));
}

export function usePmPanel(spec: ImproveSpec, open: boolean, page: HTMLElement | null, screen = 'app') {
  const [state, dispatch] = useReducer(pointReducer, undefined, createPointState);
  const [problem, setProblem] = useState<string>();
  const [live, setLive] = useState<PmTranscript>({ text: '' });
  const [dictated, setDictated] = useState<number>();
  const [speech, setSpeech] = useState<PmTranscript>({ text: '' });
  const [focusVersion, setFocusVersion] = useState(0);
  const latest = useRef({ spec, state, open, dictated, speech });
  const mounted = useRef(false), pendingBatch = useRef<CaptureBatch | undefined>(undefined), batchSequence = useRef(0);
  const batchPrefix = useId();
  useLayoutEffect(() => { mounted.current = true; return () => { mounted.current = false; }; }, []);
  useLayoutEffect(() => { latest.current = { spec, state, open, dictated, speech }; });
  const snapshot = useSyncExternalStore(spec.controller.subscribe, spec.controller.getSnapshot, spec.controller.getSnapshot);
  const policy = spec.policy ?? defaultPolicy;
  const voiceConfig = spec.pointVoice ?? spec.voice;
  const core = useVoiceAttempt<{ readonly controller: NativeChatController; readonly config: PmVoice; readonly offset: number; readonly priorSpeech: PmTranscript }>({
    valid: item => latest.current.open && latest.current.spec.controller === item.controller,
    refused: refusal => setProblem(frenchChatLabels[voiceRefusalLabel[refusal.code ?? 'failed']]),
  });
  const coreRef = useRef(core);
  useLayoutEffect(() => { coreRef.current = core; });
  const item = core.attempts[0];
  const recording = item?.phase === 'recording' || item?.phase === 'starting';
  const cancel = useCallback(() => {
    const attempt = coreRef.current.current()[0], current = latest.current;
    if (attempt?.controller === current.spec.controller) keepMarkers(attempt.controller, current.state.chips);
    coreRef.current.clear(); setLive({ text: '' });
  }, []);
  // eslint-disable-next-line react-hooks/set-state-in-effect -- a close releases this viewer's microphone and live transcript once, never native work
  useEffect(() => { if (!open) cancel(); }, [open, cancel]);
  // eslint-disable-next-line react-hooks/set-state-in-effect -- a new borrowed controller fences and releases the old viewer's capture once
  useEffect(() => { dispatch({ type: 'return' }); cancel(); }, [spec.controller, cancel]);
  useEffect(() => { if (open) dispatch({ type: 'return' }); }, [open]);
  useEffect(() => {
    if (!item || !item.config.live) return;
    return item.config.live(item.abort.signal, transcript => { if (coreRef.current.valid(item)) setLive(transcript); });
  }, [item]);
  const start = useCallback(() => {
    const current = latest.current, api = coreRef.current;
    const config = current.spec.pointVoice ?? current.spec.voice;
    if (!config || api.current().length || !current.open) return;
    setProblem(undefined); setLive({ text: '' });
    api.start({ controller: current.spec.controller, config, offset: current.dictated ?? 0, priorSpeech: current.speech }, config.maxMs);
  }, []);
  const finish = useCallback(() => {
    const api = coreRef.current, attempt = api.current()[0];
    if (!attempt) return;
    dispatch({ type: 'return' });
    if (attempt.phase === 'processing') return;
    if (attempt.phase === 'starting') { keepMarkers(attempt.controller, latest.current.state.chips); api.remove(attempt); setFocusVersion(value => value + 1); return; }
    void (async () => {
      try {
        const audio = await api.stop(attempt);
        if (!api.valid(attempt)) return;
        if (!audio) throw new Error('Rien n’a été entendu.');
        const result = await attempt.config.transcribe(audio.audio, attempt.abort.signal);
        if (!api.valid(attempt)) return;
        const transcript = typeof result === 'string' ? { text: result } : result;
        if (!transcript.text.trim()) throw new Error('Rien n’a été entendu.');
        const current = latest.current;
        const typed = attempt.controller.getSnapshot().draft.text;
        const timed = current.state.chips.filter(chip => !typed.includes(marker(chip.number))).map(chip => ({ ...chip, at: Math.max(0, chip.at - attempt.offset) }));
        const words = alignedTranscript(transcript.text.trim(), transcript.segments, timed);
        attempt.controller.setText(appendToDraft(attempt.controller.getSnapshot().draft.text, words));
        const segments = transcript.segments?.map(segment => ({ ...segment, start: segment.start + attempt.offset, end: segment.end + attempt.offset,
          ...(segment.words ? { words: segment.words.map(word => ({ ...word, start: word.start + attempt.offset, end: word.end + attempt.offset })) } : {}) }));
        setDictated(attempt.offset + (audio.endedAt - audio.startedAt) / 1000);
        setSpeech({ text: appendToDraft(attempt.priorSpeech.text, transcript.text), segments: [...(attempt.priorSpeech.segments ?? []), ...(segments ?? [])] }); setLive({ text: '' }); setFocusVersion(value => value + 1); dispatch({ type: 'return' });
      } catch { if (api.valid(attempt)) { keepMarkers(attempt.controller, latest.current.state.chips); setFocusVersion(value => value + 1); setProblem('La transcription a échoué. Vos éléments et votre texte sont conservés.'); } }
      finally { if (api.valid(attempt)) api.remove(attempt); }
    })();
  }, []);
  const voice: VoiceMessageHandle = {
    canStart: Boolean(voiceConfig) && open && snapshot.connection.kind === 'connected' && snapshot.send.kind !== 'unknown' && snapshot.send.kind !== 'submitting' && snapshot.send.kind !== 'validating', phase: item?.phase ?? 'idle', seconds: item?.seconds ?? 0,
    captureSequence: core.captureSequence, levels: item?.levels ?? [], paused: item?.paused ?? false, pending: [], problem,
    start, finish, cancel,
    ...(item?.canPause ? { pause: () => core.pause(item), resume: () => core.resume(item) } : {}),
  };
  const selectedElements = useRef(new Map<string, Element>());
  const anchors = useRef(new Map<string, import('@hachej/boring-feedback/page').AppElementAnchor>());
  const selectionRoot = page?.closest('[data-pm-layout]') ?? page;
  useEffect(() => {
    if (!open || !state.show || state.mode !== 'point' || !selectionRoot) return;
    const picker = createPicker({ root: selectionRoot, policy, styles: '.box { background: transparent; border-color: var(--border); } .label { display: none; }', tap: 'pick', wheel: false, keys: 'outside-ignored', onPick: element => {
      if (latest.current.state.chips.length >= 20) { setProblem('20 éléments maximum par message.'); return; }
      const capture = anchorOf(element, policy, { root: selectionRoot });
      if (capture.kind !== 'captured') { setProblem('Cet élément ne peut pas être joint.'); return; }
      try {
        const anchor = capture.anchor, image = captureElement(element, policy), box = element.getBoundingClientRect();
        const id = `pm-${++sequence.current}`, number = latest.current.state.nextNumber;
        const kind = feedbackLabelsFr.element(anchor.signals.role ?? element.localName, undefined);
        const label = anchor.signals.name ?? kind;
        const name = `${marker(number)} @ ${kind} · ${label} · capture jointe`;
        const controller = latest.current.spec.controller;
        controller.setAttachments([...controller.getSnapshot().draft.attachments, { id, name, content: { type: 'image', ...image } }]);
        selectedElements.current.set(id, element); anchors.current.set(id, anchor);
        const attempt = coreRef.current.current()[0];
        const at = (attempt?.offset ?? latest.current.dictated ?? 0) + (attempt?.capture.progress()?.elapsedMs ?? 0) / 1000;
        dispatch({ type: 'pick', chip: { id, kind, label, screen, at, box: [box.x, box.y, box.width, box.height] } });
        setProblem(undefined);
      } catch { setProblem('La capture de cet élément est indisponible. Réessayez.'); }
    } });
    void picker.start();
    return () => picker.dispose();
  }, [open, state.show, state.mode, policy, selectionRoot, page, screen]);
  const sequence = useRef(0);
  // Native attachment remove controls also remove the corresponding marker and pin.
  useEffect(() => {
    for (const chip of state.chips) if (!pendingBatch.current?.ids.includes(chip.id) && !snapshot.draft.attachments.some(attachment => attachment.id === chip.id) && snapshot.send.kind !== 'submitting' && snapshot.send.kind !== 'unknown' && snapshot.send.kind !== 'validating') {
      dispatch({ type: 'remove', id: chip.id }); selectedElements.current.delete(chip.id); anchors.current.delete(chip.id);
    }
  }, [snapshot.draft.attachments, snapshot.send.kind, state.chips]);
  useEffect(() => {
    if (!open || (state.mode !== 'point' && state.mode !== 'navigate') || !selectionRoot) return;
    const overlay = createOverlay({ document: selectionRoot.ownerDocument, styles: '.box { border-color: var(--border); }' });
    const elements = new Map<Element, string[]>();
    for (const chip of state.chips) {
      const element = selectedElements.current.get(chip.id);
      if (!element?.isConnected || !element.getClientRects().length) continue;
      elements.set(element, [...(elements.get(element) ?? []), marker(chip.number)]);
    }
    overlay.draw([...elements].map(([element, numbers]) => ({ element, label: numbers.join(' '), tone: 'hover' as const })));
    return () => overlay.dispose();
  }, [open, state.mode, state.chips, selectionRoot, screen]);
  const completeBatch = useCallback((batch: CaptureBatch) => {
    if (!mounted.current || latest.current.spec.controller !== batch.controller || pendingBatch.current !== batch) return;
    pendingBatch.current = undefined;
    dispatch({ type: 'sent', ids: batch.ids });
    if (latest.current.speech === batch.speech) { setDictated(undefined); setSpeech({ text: '' }); }
    for (const id of batch.ids) { selectedElements.current.delete(id); anchors.current.delete(id); }
  }, []);
  const sendContext = useMemo(() => {
    const context = {};
    return {
      count: state.chips.length || (dictated !== undefined ? 1 : 0),
      attach: (text: string) => {
        if (pendingBatch.current) return Promise.resolve({ kind: 'refused' as const, reason: 'Vérifiez d’abord le message en cours.' });
        const payload = { format: 'pm.points@1', captureBatch: `${batchPrefix}-${++batchSequence.current}`, dictatedSeconds: dictated,
          transcriptSegments: speech.segments ?? [], alignment: speech.segments?.some(segment => segment.words?.length) ? 'word' : speech.segments?.length ? 'segment' : 'unavailable',
          policy: { version: policy.version, widened: policy.widened }, selections: state.chips.map(({ id, number, kind, label, screen, at }) => ({ n: number, kind, label, screen,
            atMs: Math.round(at * 1000), screenshot: { imageIndex: snapshot.draft.attachments.findIndex(image => image.id === id), mimeType: snapshot.draft.attachments.find(image => image.id === id)?.content.mimeType }, anchor: anchors.current.get(id) })) };
        const attached = appendToDraft(text, `${POINT_PREFACE}${JSON.stringify(payload)}`);
        const selected: CaptureBatch = { context, controller: spec.controller, ids: state.chips.map(chip => chip.id), text: attached, speech,
          priorRequestId: 'attempt' in snapshot.send ? snapshot.send.attempt.requestId : undefined };
        pendingBatch.current = selected;
        return Promise.resolve({ kind: 'ok' as const, text: attached });
      },
      sent: () => { const selected = pendingBatch.current; if (selected?.context === context) completeBatch(selected); },
    };
  }, [state.chips, dictated, policy, speech, snapshot.draft.attachments, snapshot.send, spec.controller, batchPrefix, completeBatch]);
  // Reconciliation observes the original native request; it is never another send or a second admission authority.
  useEffect(() => {
    const batch = pendingBatch.current;
    if (!batch || batch.controller !== spec.controller) return;
    if ('attempt' in snapshot.send && snapshot.send.attempt.draft.text === batch.text && snapshot.send.attempt.requestId !== batch.priorRequestId) {
      batch.requestId ??= snapshot.send.attempt.requestId;
      if (snapshot.send.kind === 'admitted' && batch.requestId === snapshot.send.attempt.requestId) completeBatch(batch);
    } else if (snapshot.send.kind === 'blocked') pendingBatch.current = undefined;
  }, [snapshot.send, spec.controller, completeBatch]);
  const liveText = recording ? alignedTranscript(live.text, live.segments, state.chips.filter(chip => !snapshot.draft.text.includes(marker(chip.number))).map(chip => ({ ...chip, at: Math.max(0, chip.at - (item?.offset ?? 0)) }))) : '';
  const remove = (id: string) => {
    const chip = state.chips.find(value => value.id === id);
    if (!chip) return;
    spec.controller.setText(spec.controller.getSnapshot().draft.text.replace(marker(chip.number), ''));
    spec.controller.setAttachments(spec.controller.getSnapshot().draft.attachments.filter(image => image.id !== id));
    dispatch({ type: 'remove', id }); selectedElements.current.delete(id); anchors.current.delete(id);
  };
  const returnToComposer = () => {
    if (recording) { finish(); return; }
    keepMarkers(spec.controller, state.chips);
    dispatch({ type: 'return' }); setFocusVersion(value => value + 1);
  };
  return { state, dispatch, voice, recording, problem, liveText, sendContext, dictated, snapshot, remove, returnToComposer, focusVersion };
}

export type PmPanelState = ReturnType<typeof usePmPanel>;

import type { SpeechSegment } from '@hachej/boring-feedback/page';

export interface PointChip {
  readonly id: string;
  readonly number: number;
  readonly kind: string;
  readonly label: string;
  readonly screen: string;
  /** Seconds from this recording's first audio sample, not a wall clock. */
  readonly at: number;
  readonly box: readonly [number, number, number, number];
  readonly capture?: { readonly mimeType: string; readonly data: string };
}

export interface PointState {
  readonly mode: 'sheet' | 'point' | 'navigate' | 'full';
  readonly show: boolean;
  readonly chips: readonly PointChip[];
  readonly nextNumber: number;
}

export type PointEvent =
  | { readonly type: 'show'; readonly value: boolean }
  | { readonly type: 'return' | 'full' | 'collapse' }
  | { readonly type: 'pick'; readonly chip: Omit<PointChip, 'number'> }
  | { readonly type: 'remove'; readonly id: string }
  | { readonly type: 'sent'; readonly ids?: readonly string[] };

/** Local presentation only; routing and the borrowed composer's recording lifecycle stay with their owners. */
export function createPointState(): PointState {
  return { mode: 'sheet', show: false, chips: [], nextNumber: 1 };
}

export function pointReducer(state: PointState, event: PointEvent): PointState {
  switch (event.type) {
    case 'show': return { ...state, show: event.value, mode: event.value ? 'point' : 'navigate' };
    case 'return':
    case 'collapse': return { ...state, mode: 'sheet', show: false };
    case 'full': return { ...state, mode: 'full' };
    case 'remove': return { ...state, chips: state.chips.filter(chip => chip.id !== event.id) };
    case 'sent': {
      const chips = event.ids ? state.chips.filter(chip => !event.ids!.includes(chip.id)) : [];
      return { ...state, mode: 'full', show: false, chips, nextNumber: chips.length ? state.nextNumber : 1 };
    }
    case 'pick': {
      const chip: PointChip = { ...event.chip, box: [...event.chip.box], number: state.nextNumber,
        ...(event.chip.capture ? { capture: { ...event.chip.capture } } : {}) };
      return { ...state, chips: [...state.chips, chip], nextNumber: state.nextNumber + 1 };
    }
  }
}

export function marker(number: number): string {
  if (Number.isInteger(number) && number >= 1 && number <= 20) return String.fromCodePoint(0x2460 + number - 1);
  if (Number.isInteger(number) && number >= 21 && number <= 35) return String.fromCodePoint(0x3251 + number - 21);
  if (Number.isInteger(number) && number >= 36 && number <= 50) return String.fromCodePoint(0x32b1 + number - 36);
  return `(${number})`;
}

interface TranscriptBoundary { readonly at: number; readonly offset: number }
const timed = (span: { readonly start: number; readonly end: number }): boolean =>
  Number.isFinite(span.start) && Number.isFinite(span.end) && span.start >= 0 && span.end >= span.start;

/** Only exact matches in the canonical transcript establish offsets; timed segment text is never appended a second time. */
function transcriptBoundaries(text: string, segments: readonly SpeechSegment[]): readonly TranscriptBoundary[] {
  const boundaries: TranscriptBoundary[] = [];
  let cursor = 0;
  for (const segment of [...segments].sort((a, b) => a.start - b.start)) {
    const value = segment.text.trim();
    if (!timed(segment) || !value) continue;
    const start = text.indexOf(value, cursor);
    if (start < 0) continue;
    const end = start + value.length;
    boundaries.push({ at: segment.start, offset: start }, { at: segment.end, offset: end });
    let wordCursor = start;
    for (const word of segment.words ?? []) {
      const value = word.text.trim();
      if (!timed(word) || word.start < segment.start || word.end > segment.end || !value) continue;
      const offset = text.indexOf(value, wordCursor);
      if (offset < 0 || offset + value.length > end) continue;
      boundaries.push({ at: word.start, offset }, { at: word.end, offset: offset + value.length });
      wordCursor = offset + value.length;
    }
    cursor = end;
  }
  return boundaries;
}

/** Timings place markers at the nearest proven boundary. Without usable timing the markers follow the text, not an invented alignment. */
export function alignedTranscript(text: string, segments: readonly SpeechSegment[] | undefined, chips: readonly PointChip[]): string {
  const boundaries = transcriptBoundaries(text, segments ?? []);
  const insertions = new Map<number, string[]>();
  for (const chip of [...chips].sort((a, b) => a.at - b.at || a.number - b.number)) {
    let nearest: TranscriptBoundary | undefined;
    if (Number.isFinite(chip.at)) {
      for (const boundary of boundaries) {
        if (!nearest || Math.abs(boundary.at - chip.at) < Math.abs(nearest.at - chip.at)) nearest = boundary;
      }
    }
    const offset = nearest?.offset ?? text.length;
    const values = insertions.get(offset) ?? [];
    values.push(marker(chip.number));
    insertions.set(offset, values);
  }
  let result = '', cursor = 0;
  for (const [offset, values] of [...insertions].sort(([a], [b]) => a - b)) {
    result += text.slice(cursor, offset);
    const before = offset > 0 && !/\s/u.test(text[offset - 1]!) ? ' ' : '';
    const after = offset < text.length && !/[\s.,;:!?…)\]}>]/u.test(text[offset]!) ? ' ' : '';
    result += `${before}${values.join(' ')}${after}`;
    cursor = offset;
  }
  return result + text.slice(cursor);
}

import { serializeElement } from '@hachej/boring-feedback/page';
import type { AppDomNode, PrivacyPolicy } from '@hachej/boring-feedback/page';

/** Rasterize the policy-filtered DOM at its observed layout. Never copy HTML, URLs, media, canvas pixels or form values. */
export function captureElement(element: Element, policy: PrivacyPolicy): { readonly mimeType: 'image/png'; readonly data: string } {
  const snapshot = serializeElement(element, policy);
  if (!snapshot.root || snapshot.truncated) throw new Error('La capture de cet élément est indisponible.');
  const box = element.getBoundingClientRect();
  const canvas = element.ownerDocument.createElement('canvas');
  const scale = Math.min(1, 720 / Math.max(1, box.width), 480 / Math.max(1, box.height));
  canvas.width = Math.max(1, Math.ceil(box.width * scale)); canvas.height = Math.max(1, Math.ceil(box.height * scale));
  const context = canvas.getContext('2d');
  if (!context) throw new Error('La capture de cet élément est indisponible.');
  context.scale(scale, scale);
  context.fillStyle = getComputedStyle(element.ownerDocument.documentElement).getPropertyValue('--background');
  context.fillRect(0, 0, box.width, box.height);
  const draw = (live: Element, node: AppDomNode) => {
    const rect = live.getBoundingClientRect(), style = getComputedStyle(live);
    const x = rect.left - box.left, y = rect.top - box.top;
    context.fillStyle = style.backgroundColor; context.fillRect(x, y, rect.width, rect.height);
    const strokeWidth = parseFloat(style.borderTopWidth) || 0;
    if (strokeWidth) { context.lineWidth = strokeWidth; context.strokeStyle = style.borderTopColor; context.strokeRect(x + strokeWidth / 2, y + strokeWidth / 2, Math.max(0, rect.width - strokeWidth), Math.max(0, rect.height - strokeWidth)); }
    if (node.text) {
      context.fillStyle = style.color; context.font = style.font; context.textBaseline = 'top';
      const padding = parseFloat(style.paddingLeft) || 0, top = parseFloat(style.paddingTop) || 0;
      const width = Math.max(1, rect.width - padding - (parseFloat(style.paddingRight) || 0));
      let line = '', offset = 0;
      for (const word of node.text.split(' ')) {
        if (line && context.measureText(`${line} ${word}`).width > width) { context.fillText(line, x + padding, y + top + offset, width); line = word; offset += parseFloat(style.lineHeight) || parseFloat(style.fontSize); }
        else line += `${line ? ' ' : ''}${word}`;
      }
      if (line) context.fillText(line, x + padding, y + top + offset, width);
    }
    for (const child of node.children) {
      const match = [...live.children].filter(candidate => candidate.localName === child.tag)[child.index];
      if (match) draw(match, child);
    }
  };
  draw(element, snapshot.root);
  return { mimeType: 'image/png', data: canvas.toDataURL('image/png').split(',')[1]! };
}

import type { EntryRecord } from '@earendil-works/pi-durable';
import { Bubble, BubbleContent } from '@/components/ui/bubble';
